-- 0009_add_intake_review — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- Intake review (SOP-DEL-01 §8, §9; E2 AC2–AC4): Delivery's decision on one version of a Handover Card,
-- the conditions it sets, and a Conditional Start authorised before acceptance. Internal only, like the card.
-- Which items may be conditions (never A1, A4, A6, C2, D1, F1), the 5-working-day limit and who may
-- authorise a Conditional Start are rules and permissions in core/intake, cited there.
CREATE TABLE intake_decision (
  id               uuid PRIMARY KEY,
  client_id        uuid NOT NULL,
  -- One decision per card version; a Returned card comes back as the next version (§8).
  card_id          uuid NOT NULL UNIQUE,
  decision         text NOT NULL CHECK (decision IN ('accepted', 'accepted_with_conditions', 'returned')),
  folder_standard  text NOT NULL CHECK (folder_standard IN ('L', 'S', 'mixed')),
  -- §8 Returned: "The Delivery Director lists every gap in the Handover Card."
  reasons          text,
  assigned_pm_id   uuid,
  handover_meeting date,
  transfer_date    date,
  decided_by       uuid NOT NULL,
  decided_at       timestamptz NOT NULL DEFAULT now(),
  archived_at      timestamptz,
  UNIQUE (id, client_id),
  CHECK (decision <> 'returned' OR (reasons IS NOT NULL AND btrim(reasons) <> '')),
  -- §8 box: until a project is accepted, Delivery does not assign a Project Manager.
  CHECK (decision <> 'returned' OR assigned_pm_id IS NULL),
  FOREIGN KEY (card_id, client_id) REFERENCES handover_card (id, client_id)
);
CREATE INDEX intake_decision_client ON intake_decision (client_id);

-- §8 Accepted with conditions: each missing non-blocking item with a deadline.
CREATE TABLE intake_condition (
  id          uuid PRIMARY KEY,
  client_id   uuid NOT NULL,
  decision_id uuid NOT NULL,
  item_code   text NOT NULL CHECK (item_code ~ '^[A-G][1-9]$'),
  text        text NOT NULL CHECK (btrim(text) <> ''),
  deadline    date NOT NULL,
  status      text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'met', 'expired')),
  met_at      timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz,
  UNIQUE (decision_id, item_code),
  CHECK ((status = 'met') = (met_at IS NOT NULL)),
  FOREIGN KEY (decision_id, client_id) REFERENCES intake_decision (id, client_id)
);
CREATE INDEX intake_condition_client ON intake_condition (client_id);
-- Alerts on expiry (AC3) scan open conditions by deadline.
CREATE INDEX intake_condition_open ON intake_condition (deadline) WHERE status = 'open';

-- §9 Conditional Start: Delivery starts before acceptance, authorised in writing, naming the missing items
-- and a deadline. The items stay Sales' responsibility.
CREATE TABLE conditional_start (
  id            uuid PRIMARY KEY,
  client_id     uuid NOT NULL,
  card_id       uuid NOT NULL,
  authorised_by uuid NOT NULL,
  missing_items text[] NOT NULL CHECK (cardinality(missing_items) >= 1),
  deadline      date NOT NULL,
  -- The written authorisation in DingTalk (§9): message link or reference.
  written_ref   text NOT NULL CHECK (btrim(written_ref) <> ''),
  created_at    timestamptz NOT NULL DEFAULT now(),
  archived_at   timestamptz,
  FOREIGN KEY (card_id, client_id) REFERENCES handover_card (id, client_id)
);
CREATE INDEX conditional_start_client ON conditional_start (client_id);

ALTER TABLE intake_decision ENABLE ROW LEVEL SECURITY;
CREATE POLICY intake_decision_internal ON intake_decision FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
ALTER TABLE intake_condition ENABLE ROW LEVEL SECURITY;
CREATE POLICY intake_condition_internal ON intake_condition FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
ALTER TABLE conditional_start ENABLE ROW LEVEL SECURITY;
CREATE POLICY conditional_start_internal ON conditional_start FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
-- No client or partner policy. No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON intake_decision, intake_condition, conditional_start TO ocs_app;
